type PrinterRow={id:string;code:string;name:string;manufacturer:string;model:string;technology:number;status:number;notes:string|null;averageWatts:number;nominalWatts:number;machineHour:number|null;slotCount:number;buildVolume:string;extruders:number;compatibleMaterials:string;acquisitionCost:number|null;lifespanHours:number};
type Spool={id:string;balanceId:string;code:string;material:string;color:string;batch:string|null;initialGrams:number;remainingGrams:number;reservedGrams:number;availableGrams:number;active:boolean;costPerGram:number|null};
type Balance={id:string;skuCode:string;name:string;warehouse:string;kind:"FILAMENT"|"SUPPLY"|null;material:string|null;color:string|null;unitsPerStockUnit:number|null;onHand:number;reserved:number;blocked:number;available:number;averageCost:number|null};
type Order={orderType:number;targetSkuId:string|null;targetWarehouseId:string|null;stockPostedAt:string|null;stockQuantity:number|null;accountingState:string|null;saleId:string|null;designVersionId:string|null;id:string;number:string;title:string;notes:string;customer:string;customerId:string;dueAt:string|null;status:number;version:number;printerId:string;quantity:number;produced:number;approved:number;rejected:number;seconds:number;estimatedGrams:number;estimatedCost:number|null;actualCost:number|null;wasteCost:number|null;approvedPrice:number|null;estimateSnapshot:Record<string,number>|null;cancelReason:string|null;failureReason:string|null;createdAt:string;startedAt:string|null;finishedAt:string|null;activeAttemptId:string|null};
type Allocation={id:string;orderId:string;balanceId:string;spoolId:string|null;kind:string;material:string;color:string;spoolCode:string|null;planned:number;actual:number|null;state:"RESERVED"|"CONSUMED"|"RELEASED";waste:boolean|null;unitCost:number|null;actualCost:number|null;stockCost:number|null};
type Attempt={id:string;orderId:string;number:number;printerId:string;status:number;operator:string|null;estimatedSeconds:number;actualSeconds:number|null;grams:number;notes:string|null;startedAt:string;closedAt:string|null;energyCost:number|null;machineCost:number|null;laborCost:number|null};
type Capability={stockOrder:boolean;catalogIntake:boolean;libraryManage:boolean;costs:boolean;commercial:boolean;inventory:boolean;printer:boolean;printerStatus:boolean;inventoryManage:boolean;order:boolean;manageOrder:boolean;execute:boolean;quality:boolean;quote:boolean;slot:boolean};
type FactoryData={finishedSkus:{id:string;code:string;name:string}[];outputWarehouses:{id:string;name:string;code:string}[];versions:DesignVersion[];recipes:Recipe[];receipts:Receipt[];printers:PrinterRow[];spools:Spool[];balances:Balance[];customers:{id:string;name:string}[];orders:Order[];materials:Allocation[];attempts:Attempt[];slots:{printerId:string;slot:number;spoolId:string}[];summary:{total:number;queued:number;printing:number;assembly:number;ready:number;cancelled:number;actualCost:number|null;wasteCost:number|null};legacy:{orders:number;spools:number};library:{id:string;code:string;title:string;category:string;description:string|null;license:string;commercialAllowed:boolean;author:string|null;versions:number}[];billingReady:boolean;capabilities:Capability};
type SlicePlate={index:number;seconds:number|null;preparationSeconds:number|null;totalGrams:number|null;filaments:{slot:number;grams:number|null;color:string|null;material:string|null}[];warnings:string[]};
type DesignVersion={id:string;assetId:string;revision:string;format:string;bytes:number;sha256:string;notes:string|null;filename:string|null;metadata:{source:string;plates:SlicePlate[];warnings:string[]}|null;downloadable:boolean};
type Recipe={versionId:string;batchQuantity:number;seconds:number;laborSeconds:number;notes:string;lines:{balanceId:string;quantity:number;material:string;color:string;kind:string}[]};
type Receipt={id:string;balanceId:string;number:string;supplier:string;received:number;remaining:number;unitCost:number|null};
type PlanLine={key:string;selection:string;quantity:string;hint?:string;balanceId?:string};
type Send=(action:string,data:Record<string,unknown>,refresh?:boolean)=>Promise<any>;
type ModalKind="order"|"printer"|"configureFilament"|"configureSupply"|"spools"|"newSupply"|"detail"|"printerStatus"|"slot";
type Modal={kind:ModalKind;id?:string;target?:number};
const box="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm";
const input="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-800 outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-100 disabled:bg-slate-100";
const primary="inline-flex items-center justify-center gap-2 rounded-lg bg-purple-700 px-4 py-2 text-sm font-semibold text-white hover:bg-purple-800 disabled:opacity-50";
const secondary="inline-flex items-center justify-center gap-2 rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50";
const money=(n:number|null|undefined)=>n===null||n===undefined?"—":n.toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const num=(n:number|null|undefined)=>n===null||n===undefined?"—":n.toLocaleString("pt-BR",{maximumFractionDigits:3});
const duration=(n:number|null|undefined)=>n===null||n===undefined?"—":Math.floor(n/3600)+"h "+Math.floor(n%3600/60)+"m "+Math.floor(n%60)+"s";
const date=(v:string|null)=>v?new Date(v).toLocaleString("pt-BR",{dateStyle:"short",timeStyle:"short"}):"—";
const orderStatus:Record<number,string>={7:"Fila de espera",8:"Iniciado",10:"Fase de montagem",12:"Pronto",13:"Cancelado"};
const printerStatus:Record<number,string>={1:"Disponível",2:"Reservada",3:"Preparando",4:"Imprimindo",5:"Pausada",6:"Finalizando",7:"Manutenção",8:"Fora de serviço"};
const stages=[{id:7,name:"Fila de espera",tone:"border-t-slate-400"},{id:8,name:"Iniciado",tone:"border-t-blue-500"},{id:10,name:"Fase de montagem",tone:"border-t-amber-500"},{id:12,name:"Pronto",tone:"border-t-emerald-500"}];
function Field({label,name,type="text",value,step,min,max,required=true,placeholder}:{label:string;name:string;type?:string;value?:string|number;step?:string;min?:number;max?:number;required?:boolean;placeholder?:string}){return <label className="block space-y-1 text-xs font-medium text-slate-600"><span>{label}</span><input className={input} name={name} type={type} defaultValue={value} step={step} min={min} max={max} required={required} placeholder={placeholder}/></label>;}
function Select({label,name,options,value,required=true}:{label:string;name:string;options:{value:string;label:string}[];value?:string;required?:boolean}){return <label className="block space-y-1 text-xs font-medium text-slate-600"><span>{label}</span><select className={input} name={name} defaultValue={value||""} required={required}><option value="">Selecione</option>{options.map(x=><option key={x.value} value={x.value}>{x.label}</option>)}</select></label>;}
function Empty({children}:{children:React.ReactNode}){return <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-6 text-center text-sm text-slate-500">{children}</div>;}
function formValues(form:HTMLFormElement){return Object.fromEntries(new FormData(form).entries());}
const str=(f:Record<string,FormDataEntryValue>,k:string)=>String(f[k]??"");
const number=(f:Record<string,FormDataEntryValue>,k:string)=>Number(f[k]??0);
function ModalFrame({title,close,busy,children}:{title:string;close:()=>void;busy:boolean;children:React.ReactNode}){return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-3" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)close();}}><section role="dialog" aria-modal="true" aria-label={title} className="max-h-[92vh] w-full max-w-5xl overflow-y-auto rounded-2xl border bg-white shadow-2xl"><header className="sticky top-0 z-10 flex items-center justify-between gap-3 border-b bg-white px-5 py-4"><h2 className="text-lg font-bold text-slate-900">{title}</h2><button className={secondary} type="button" disabled={busy} onClick={close}>Fechar</button></header><div className="p-5">{children}</div></section></div>;}
function materialOptions(d:FactoryData){return [...d.spools.filter(s=>s.active&&s.availableGrams>0).map(s=>({value:"spool:"+s.id,label:s.material+" "+s.color+" • "+s.code+" ("+num(s.availableGrams)+" g)"})),...d.balances.filter(s=>s.kind==="SUPPLY"&&s.available>0).map(s=>({value:"supply:"+s.id,label:s.material+" • "+s.name+" ("+num(s.available)+" un.)"}))];}
function materialLine(d:FactoryData,selection:string,qty:string|number){const [kind,id]=selection.split(":");const spool=d.spools.find(x=>x.id===id);if(kind==="spool"&&spool)return {balanceId:spool.balanceId,spoolId:spool.id,quantity:Number(qty)};if(kind==="supply"&&d.balances.some(x=>x.id===id&&x.kind==="SUPPLY"))return {balanceId:id,spoolId:null,quantity:Number(qty)};throw new Error("Selecione um material válido.");}
function PrinterForm({send,busy,close}:{send:Send;busy:boolean;close:()=>void}){return <form className="space-y-4" onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);const data={code:str(f,"code"),name:str(f,"name"),manufacturer:str(f,"manufacturer"),model:str(f,"model"),serial:str(f,"serial"),technology:number(f,"technology"),buildVolume:str(f,"buildVolume"),extruders:number(f,"extruders"),slotCount:number(f,"slotCount"),materials:str(f,"materials"),nominalWatts:number(f,"nominalWatts"),averageWatts:number(f,"averageWatts"),acquisitionCost:number(f,"acquisitionCost"),lifespanHours:number(f,"lifespanHours"),machineHour:number(f,"machineHour")};void send("createPrinter",data).then(close).catch(()=>{});}}><fieldset disabled={busy} className="grid gap-3 sm:grid-cols-2"><Field label="Código" name="code"/><Field label="Nome do equipamento" name="name"/><Field label="Fabricante" name="manufacturer"/><Field label="Modelo" name="model"/><Field label="Número de série" name="serial" required={false}/><Select label="Tecnologia" name="technology" value="1" options={[{value:"1",label:"FDM / FFF"},{value:"2",label:"SLA / Resina"},{value:"3",label:"SLS"}]}/><Field label="Volume de impressão (mm)" name="buildVolume" placeholder="Ex.: 256 × 256 × 256"/><Field label="Materiais compatíveis" name="materials" placeholder="PLA, PETG"/><Field label="Extrusoras" name="extruders" type="number" min={1} max={32} value={1}/><Field label="Slots físicos de material" name="slotCount" type="number" min={1} max={32} value={1}/><Field label="Potência nominal (W)" name="nominalWatts" type="number" min={1} step="0.01"/><Field label="Potência média medida/estimada (W)" name="averageWatts" type="number" min={1} step="0.01"/><Field label="Valor de aquisição (R$)" name="acquisitionCost" type="number" min={0} step="0.01"/><Field label="Vida útil estimada (h)" name="lifespanHours" type="number" min={1} step="1"/><Field label="Custo hora-máquina (R$/h, sem energia e mão de obra)" name="machineHour" type="number" min={0} step="0.0001"/></fieldset><p className="text-xs text-slate-500">Informe a potência real ou a estimativa documentada do equipamento. A taxa horária deve incluir depreciação/manutenção sem duplicar energia.</p><button disabled={busy} className={primary}>Cadastrar impressora</button></form>;}
function ConfigureForm({d,kind,send,busy,close}:{d:FactoryData;kind:"FILAMENT"|"SUPPLY";send:Send;busy:boolean;close:()=>void}){return <form className="space-y-4" onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);void send("configureMaterial",{balanceId:str(f,"balanceId"),kind,material:str(f,"material"),color:kind==="FILAMENT"?str(f,"color"):"",unitsPerStockUnit:kind==="FILAMENT"?number(f,"factor"):1}).then(close).catch(()=>{});}}><p className="text-sm text-slate-600">Vincule um saldo existente do catálogo/estoque. Esta configuração não cria uma compra nem aumenta o estoque.</p><fieldset disabled={busy} className="space-y-3"><Select label="Saldo central / SKU / depósito" name="balanceId" options={d.balances.filter(x=>!x.kind).map(x=>({value:x.id,label:x.skuCode+" · "+x.name+" · "+x.warehouse+" · "+num(x.available)+" disponível"}))}/><Field label={kind==="FILAMENT"?"Tipo de material (ex.: PLA)":"Nome do insumo"} name="material"/>{kind==="FILAMENT"&&<><Field label="Cor" name="color"/><Field label="Gramas por unidade do estoque central" name="factor" type="number" min={0.001} step="0.001" value={1000}/><p className="text-xs text-slate-500">Use 1 se o estoque central já está em gramas; 1000 para SKU de rolos de 1 kg. A precisão do estoque central é de seis casas decimais.</p></>}</fieldset><button disabled={busy} className={primary}>Vincular material</button></form>;}
function ExistingSpoolForm({d,send,busy,close}:{d:FactoryData;send:Send;busy:boolean;close:()=>void}){
 const [balance,setBalance]=useState("");
 return <form className="space-y-4" onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);const item=str(f,"receiptItemId");const data={balanceId:balance,count:number(f,"count"),grams:number(f,"grams"),tare:number(f,"tare"),batch:str(f,"batch")};void send(item?"registerReceivedSpools":"registerSpools",item?{...data,receiptItemId:item}:data).then(close).catch(()=>{});}}>
 <p className="text-sm text-slate-600">Identifique os rolos já existentes no estoque central. Ao selecionar um recebimento aprovado, o custo histórico do lote será registrado sem duplicar a entrada.</p>
 <fieldset disabled={busy} className="grid gap-3 sm:grid-cols-2">
 <label className="space-y-1 text-xs font-medium text-slate-600">Material / cor / depósito<select required className={input} value={balance} onChange={e=>setBalance(e.target.value)}><option value="">Selecione</option>{d.balances.filter(x=>x.kind==="FILAMENT").map(x=><option key={x.id} value={x.id}>{x.material} {x.color} · {x.warehouse} · {num(x.onHand)} unidades</option>)}</select></label>
 <Select key={balance} label="Recebimento de compra (opcional)" name="receiptItemId" required={false} options={d.receipts.filter(x=>x.balanceId===balance).map(x=>({value:x.id,label:x.number+" · "+x.supplier+" · "+num(x.remaining)+" un. não vinculadas"+(x.unitCost!==null?" · "+money(x.unitCost):"")}))}/>
 <Field label="Quantidade de rolos" name="count" type="number" min={1} max={100} value={1}/><Field label="Peso líquido de cada rolo (g)" name="grams" type="number" min={0.001} step="0.001" value={1000}/><Field label="Peso do carretel vazio (g)" name="tare" type="number" min={0} step="0.001"/><Field label="Lote / referência" name="batch" required={false}/></fieldset><p className="text-xs text-slate-500">Sem recebimento selecionado, utiliza-se o custo médio do saldo central. Não cria nota de compra nem contas a pagar.</p><button disabled={busy} className={primary}>Registrar rolos</button></form>;
}
function SpoolForm({d,send,busy,close,refresh}:{d:FactoryData;send:Send;busy:boolean;close:()=>void;refresh:()=>Promise<boolean>}){const [mode,setMode]=useState<"new"|"existing">(d.capabilities.catalogIntake?"new":"existing");return <div className="space-y-4"><div className="flex flex-wrap gap-2">{d.capabilities.catalogIntake&&<button type="button" className={mode==="new"?primary:secondary} onClick={()=>setMode("new")}>Novo filamento / entrada inicial</button>}<button type="button" className={mode==="existing"?primary:secondary} onClick={()=>setMode("existing")}>Identificar rolos já em estoque</button></div>{mode==="new"?<CatalogIntakeForm context="filament" onDone={async()=>{await refresh();close();}}/>:<>{!d.balances.some(x=>x.kind==="FILAMENT")&&<p className="rounded-lg bg-amber-50 p-3 text-sm">Ainda não há filamentos configurados. Use Novo filamento para cadastrar e registrar saldo inicial.</p>}<ExistingSpoolForm d={d} send={send} busy={busy} close={close}/></>}</div>}
function OrderForm({d,send,busy,close}:{d:FactoryData;send:Send;busy:boolean;close:()=>void}){
 const [purpose,setPurpose]=useState<"CUSTOM"|"STOCK">("CUSTOM");
 const [plan,setPlan]=useState<PlanLine[]>([{key:"1",selection:"",quantity:""}]);const seq=useRef(2);const [preview,setPreview]=useState<{estimate:Record<string,number>;fingerprint:string}|null>(null);const [price,setPrice]=useState("");const [localError,setLocalError]=useState("");const formRef=useRef<HTMLFormElement>(null);const [design,setDesign]=useState("");const [plateIndex,setPlateIndex]=useState("");const version=d.versions.find(v=>v.id===design);const recipe=d.recipes.find(r=>r.versionId===design);const setField=(k:string,v:string|number)=>{const el=formRef.current?.elements.namedItem(k);if(el instanceof HTMLInputElement||el instanceof HTMLTextAreaElement)el.value=String(v);};
 const make=(form:HTMLFormElement)=>{const f=formValues(form);const due=str(f,"dueAt");return {purpose,targetSkuId:purpose==="STOCK"?str(f,"targetSkuId"):null,targetWarehouseId:purpose==="STOCK"?str(f,"targetWarehouseId"):null,designVersionId:design||null,customerId:purpose==="CUSTOM"?str(f,"customerId"):null,printerId:str(f,"printerId"),title:str(f,"title"),notes:str(f,"notes"),quantity:number(f,"quantity"),seconds:number(f,"seconds"),laborSeconds:number(f,"laborSeconds"),tariff:number(f,"tariff"),laborHour:number(f,"laborHour"),other:number(f,"other"),wastePct:number(f,"wastePct"),marginPct:number(f,"marginPct"),feePct:number(f,"feePct"),dueAt:due?new Date(due).toISOString():null,plan:plan.map(x=>materialLine(d,x.selection,x.quantity))};};
 const calculate=()=>{const f=formRef.current;if(!f||!f.reportValidity())return;setLocalError("");try{void send("previewOrder",make(f),false).then(r=>{setPreview(r);setPrice(String(r.estimate.suggestedPrice));}).catch(()=>{});}catch(e){setLocalError(e instanceof Error?e.message:"Revise os materiais.");}};
 return <form ref={formRef} className="space-y-5" onChange={e=>{const target=e.target;if(target instanceof HTMLInputElement||target instanceof HTMLSelectElement||target instanceof HTMLTextAreaElement){if(!["approvedPrice","confirmed","title","notes","customerId","dueAt"].includes(target.name))setPreview(null);}}} onSubmit={e=>{e.preventDefault();setLocalError("");const f=formValues(e.currentTarget);if(!preview||!f.confirmed||(purpose==="CUSTOM"&&(!Number.isFinite(Number(price))||Number(price)<=0))){setLocalError("Calcule a estimativa e confirme os dados da ordem.");return;}try{void send("createOrder",{...make(e.currentTarget),approvedPrice:purpose==="STOCK"?0:Number(price),estimateFingerprint:preview.fingerprint}).then(close).catch(()=>{});}catch(err){setLocalError(err instanceof Error?err.message:"Revise os dados.");}}}>
  <fieldset disabled={busy} className="space-y-5">
   <section className="rounded-xl border border-slate-200 bg-slate-50 p-3 space-y-3"><h3 className="text-sm font-bold">Projeto e ficha técnica (opcional)</h3><label className="block text-xs font-medium text-slate-600">Versão da biblioteca<select className={input} value={design} onChange={e=>{setDesign(e.target.value);setPlateIndex("");setPreview(null);}}><option value="">Sem projeto vinculado</option>{d.versions.filter(v=>v.downloadable&&d.library.some(a=>a.id===v.assetId&&a.commercialAllowed)).map(v=><option key={v.id} value={v.id}>{d.library.find(a=>a.id===v.assetId)?.title} · {v.revision}</option>)}</select></label>
 {recipe&&<div className="space-y-2"><p className="text-xs">{recipe.batchQuantity} peças / lote · {duration(recipe.seconds)} · {recipe.lines.length} materiais</p><button type="button" className={secondary} onClick={()=>{setField("quantity",recipe.batchQuantity);setField("seconds",recipe.seconds);setField("laborSeconds",recipe.laborSeconds);setPlan(recipe.lines.map(l=>({key:String(seq.current++),selection:l.kind==="SUPPLY"?"supply:"+l.balanceId:"",quantity:String(l.quantity),hint:l.material+" "+l.color,balanceId:l.balanceId})));setPreview(null);}}>Aplicar ficha de 1 lote</button><p className="text-xs text-slate-500">Selecione o rolo físico de cada cor. Para múltiplos lotes, confirme tempo de bandejas e quantidades, sem multiplicar automaticamente a duração.</p></div>}
 {version?.metadata?.plates.length? <div className="space-y-2"><label className="block text-xs text-slate-600">Bandeja importada<select className={input} value={plateIndex} onChange={e=>setPlateIndex(e.target.value)}><option value="">Selecione a bandeja</option>{version.metadata.plates.map(p=><option key={p.index} value={String(p.index)}>Bandeja {p.index} · {duration(p.seconds)} · {num(p.totalGrams)} g</option>)}</select></label><button type="button" disabled={!plateIndex} className={secondary} onClick={()=>{const p=version.metadata?.plates.find(x=>String(x.index)===plateIndex);if(!p)return;if(p.seconds!==null)setField("seconds",p.seconds);if(p.filaments.length&&p.filaments.every(x=>x.grams!==null)){setPlan(p.filaments.filter(x=>(x.grams??0)>0).map(x=>({key:String(seq.current++),selection:"",quantity:String(x.grams),hint:"Slot "+x.slot+" · "+(x.material||"Material não informado")+" · "+(x.color||"Cor não informada")})));}setPreview(null);}}>Aplicar estimativa desta bandeja</button><p className="text-xs text-slate-500">Peso e tempo são estimativas; associe cada slot a um rolo e acrescente insumos manualmente. Se o peso só estiver disponível como total, informe a distribuição por cor.</p></div>:null}
 </section>
   <section><h3 className="mb-3 text-sm font-bold">01 · Finalidade e destino</h3><div className="mb-3 flex flex-wrap gap-2"><button type="button" className={purpose==="CUSTOM"?primary:secondary} onClick={()=>{setPurpose("CUSTOM");setPreview(null);}}>Sob encomenda</button>{d.capabilities.stockOrder&&<button type="button" className={purpose==="STOCK"?primary:secondary} onClick={()=>{setPurpose("STOCK");setPreview(null);}}>Produzir para estoque</button>}</div><div className="grid gap-3 sm:grid-cols-2">{purpose==="CUSTOM"?<Select label="Cliente do ERP" name="customerId" options={d.customers.map(c=>({value:c.id,label:c.name}))}/>:<><Select label="Produto acabado / SKU" name="targetSkuId" options={d.finishedSkus.map(c=>({value:c.id,label:c.code+" · "+c.name}))}/><Select label="Depósito de destino" name="targetWarehouseId" options={d.outputWarehouses.map(c=>({value:c.id,label:c.name+" · "+c.code}))}/>{(!d.finishedSkus.length||!d.outputWarehouses.length)&&<p className="text-xs text-amber-700 sm:col-span-2">Cadastre um produto do tipo Fabricado em 3D no <a className="underline" href="/catalog">cadastro de produtos</a> e, se necessário, um depósito em <a className="underline" href="/inventory">Estoque</a>. Não lance saldo antecipado para peças ainda não fabricadas.</p>}</>}<Select label="Impressora planejada" name="printerId" options={d.printers.filter(x=>![7,8].includes(x.status)).map(x=>({value:x.id,label:x.code+" · "+x.name}))}/><Field label="Produto / serviço solicitado" name="title"/><Field label="Quantidade de peças" name="quantity" type="number" min={1} max={100000} value={1}/><Field label="Prazo combinado" name="dueAt" type="datetime-local" required={false}/><label className="space-y-1 text-xs font-medium text-slate-600">Personalização / observações<textarea className={input} name="notes" rows={2} maxLength={4000}/></label></div></section>
   <section className="border-t pt-4"><div className="mb-3 flex items-center justify-between"><h3 className="text-sm font-bold">02 · Materiais e acessórios — total da OS</h3><button type="button" className={secondary} onClick={()=>{setPlan(x=>[...x,{key:String(seq.current++),selection:"",quantity:""}]);setPreview(null);}}>+ Material</button></div>{plan.map((x,i)=><div key={x.key} className="mb-2 grid gap-2 sm:grid-cols-[2fr_1fr_auto]"><label className="text-xs font-medium text-slate-600">{x.hint||"Material / rolo"}<select required className={input} value={x.selection} onChange={e=>{setPlan(old=>old.map(y=>y.key===x.key?{...y,selection:e.target.value}:y));setPreview(null);}}><option value="">Selecione</option>{materialOptions(d).filter(y=>!x.balanceId||y.value==="supply:"+x.balanceId||d.spools.some(s=>s.balanceId===x.balanceId&&y.value==="spool:"+s.id)).map(y=><option key={y.value} value={y.value}>{y.label}</option>)}</select></label><label className="text-xs font-medium text-slate-600">{x.selection.startsWith("supply:")?"Unidades":"Gramas"}<input className={input} type="number" required min={x.selection.startsWith("supply:")?1:0.001} step={x.selection.startsWith("supply:")?"1":"0.001"} value={x.quantity} onChange={e=>{setPlan(old=>old.map(y=>y.key===x.key?{...y,quantity:e.target.value}:y));setPreview(null);}}/></label><button type="button" className={secondary+" self-end"} onClick={()=>{setPlan(old=>old.filter(y=>y.key!==x.key));setPreview(null);}} aria-label={"Remover material "+(i+1)}>Remover</button></div>)}</section>
   <section className="border-t pt-4"><h3 className="mb-3 text-sm font-bold">03 · Tempo e precificação</h3><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><Field label="Tempo total estimado (segundos)" name="seconds" type="number" min={1} step="1"/><Field label="Tempo humano total (segundos)" name="laborSeconds" type="number" min={0} value={0}/><Field label="Tarifa elétrica (R$/kWh)" name="tariff" type="number" min={0} step="0.000001"/><Field label="Mão de obra (R$/h)" name="laborHour" type="number" min={0} step="0.000001"/><Field label="Outros custos estimados (R$)" name="other" type="number" min={0} step="0.01" value={0}/><Field label="Provisão de desperdício (%)" name="wastePct" type="number" min={0} max={100} step="0.01" value={0}/><Field label="Margem sobre venda (%)" name="marginPct" type="number" min={0} max={99.99} step="0.01"/><Field label="Taxas sobre venda (%)" name="feePct" type="number" min={0} max={99.99} step="0.01" value={0}/></div><button type="button" className={secondary+" mt-3"} onClick={calculate}><Calculator size={16}/> Calcular com custos do estoque</button></section>
   {preview&&<div className="rounded-xl border border-purple-200 bg-purple-50 p-4"><div className="grid gap-3 sm:grid-cols-3"><div><p className="text-xs text-slate-600">Custo estimado</p><p className="text-xl font-bold">{money(preview.estimate.totalCost)}</p></div><div><p className="text-xs text-slate-600">Preço sugerido</p><p className="text-xl font-bold text-purple-800">{money(preview.estimate.suggestedPrice)}</p></div><div><p className="text-xs text-slate-600">Contribuição estimada</p><p className="text-xl font-bold">{money(preview.estimate.contribution)}</p></div></div></div>}
   <section><h3 className="mb-2 text-sm font-bold">{purpose==="STOCK"?"04 · Confirmar fabricação":"04 · Preço aprovado"}</h3>{purpose==="CUSTOM"&&<label className="block space-y-1 text-xs text-slate-600">Total aprovado (R$)<input className={input} name="approvedPrice" type="number" min="0.01" step="0.01" value={price} onChange={e=>setPrice(e.target.value)}/></label>}<label className="mt-3 flex items-center gap-2 text-sm"><input name="confirmed" type="checkbox"/> {purpose==="STOCK"?"Confirmo o lote, SKU e depósito de destino.":"Confirmo o preço combinado com o cliente."}</label><p className="mt-2 text-xs text-slate-500">{purpose==="STOCK"?"O saldo de produto acabado só será creditado após a aprovação de todas as peças. O preço de venda vem do catálogo.":"Ao criar a OS, o backend valida novamente o custo e reserva os materiais. O preço aprovado permanece independente do custo real."}</p></section>
  </fieldset>{localError&&<p role="alert" className="text-sm text-red-700">{localError}</p>}<button disabled={busy||!preview} className={primary}>Criar OS e reservar materiais</button>
 </form>;
}
function Detail({o,d,send,busy,target,onTransition}:{o:Order;d:FactoryData;send:Send;busy:boolean;target?:number;onTransition:()=>void}){
 const materials=d.materials.filter(a=>a.orderId===o.id),reserved=materials.filter(a=>a.state==="RESERVED"),attempts=d.attempts.filter(a=>a.orderId===o.id),filaments=reserved.filter(a=>a.kind==="FILAMENT"),supplies=reserved.filter(a=>a.kind==="SUPPLY");const [success,setSuccess]=useState(!(o.status===8&&target===7));const actionRef=useRef<HTMLFormElement>(null);useEffect(()=>{if(target!==undefined){actionRef.current?.scrollIntoView({block:"start"});actionRef.current?.querySelector<HTMLElement>("input,select,button")?.focus({preventScroll:true});}},[target]);const pending=o.produced-o.approved-o.rejected;
 const materialLabel=(a:Allocation)=>a.material+(a.color?" "+a.color:"")+(a.spoolCode?" • "+a.spoolCode:"");
 const act=(action:string,data:Record<string,unknown>)=>{void send(action,{orderId:o.id,version:o.version,...data}).then(()=>{if(["start","finish","quality","cancel"].includes(action))onTransition();}).catch(()=>{});};
 const actualFields=(rows:Allocation[])=><div className="grid gap-2 sm:grid-cols-2">{rows.map(a=><Field key={a.id} label={materialLabel(a)+" — reservado "+num(a.planned)+(a.kind==="FILAMENT"?" g":" un.")} name={"actual_"+a.id} type="number" min={0} max={a.planned} step={a.kind==="FILAMENT"?"0.001":"1"}/>)}</div>;
 return <div className="space-y-5">
  {target!==undefined&&<div className="rounded-xl border border-purple-200 bg-purple-50 p-3 text-sm text-purple-900"><strong>{factoryTransitions(o.status,d.capabilities).find(x=>x.target===target)?.label}</strong><p>{factoryTransitions(o.status,d.capabilities).find(x=>x.target===target)?.description}</p><p className="mt-1 text-xs">A coluna só muda após a confirmação do sistema.</p></div>}
  <div className="grid gap-3 sm:grid-cols-4">{[{label:"Situação",value:orderStatus[o.status]||String(o.status)},{label:"Cliente",value:o.customer},{label:"Peças aprovadas",value:o.approved+" / "+o.quantity},{label:"Prazo",value:date(o.dueAt)}].map(x=><div key={x.label} className={box}><p className="text-xs text-slate-500">{x.label}</p><p className="font-semibold text-slate-900">{x.value}</p></div>)}</div>
  <div><h3 className="font-bold text-slate-900">{o.title}</h3><p className="whitespace-pre-wrap text-sm text-slate-600">{o.notes||"Sem observações."}</p>{o.designVersionId&&<p className="text-xs text-slate-500">Projeto: {d.versions.find(v=>v.id===o.designVersionId)?.revision||"Versão histórica vinculada"}</p>}{o.failureReason&&<p className="mt-2 text-sm text-amber-700">Última ocorrência: {o.failureReason}</p>}{o.cancelReason&&<p className="mt-2 text-sm text-red-700">Cancelamento: {o.cancelReason}</p>}</div>
  {(d.capabilities.costs||d.capabilities.commercial)&&<div className="grid gap-3 sm:grid-cols-4">{[{label:"Custo estimado",value:o.estimatedCost},{label:"Custo realizado",value:o.actualCost},{label:"Desperdício",value:o.wasteCost},{label:"Preço aprovado",value:o.approvedPrice}].map(x=>x.value!==null&&<div key={x.label} className={box}><p className="text-xs text-slate-500">{x.label}</p><p className="text-lg font-bold">{money(x.value)}</p></div>)}</div>}
  <section className={box}><h3 className="mb-3 text-sm font-bold">Materiais e histórico de consumo</h3>{materials.length===0?<Empty>Nenhum material.</Empty>:<div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead className="bg-slate-50 text-slate-500"><tr>{["Material","Planejado","Consumido","Status","Custo OS","Custo Kardex"].map(x=><th key={x} className="p-2">{x}</th>)}</tr></thead><tbody>{materials.map(a=><tr key={a.id} className="border-t"><td className="p-2 font-medium">{materialLabel(a)}</td><td className="p-2">{num(a.planned)}</td><td className="p-2">{num(a.actual)}</td><td className="p-2">{a.state==="RESERVED"?"Reservado":a.state==="RELEASED"?"Liberado":a.waste?"Refugo":"Consumido"}</td><td className="p-2">{money(a.actualCost)}</td><td className="p-2">{money(a.stockCost)}</td></tr>)}</tbody></table></div>}</section>
  {attempts.length>0&&<section className={box}><h3 className="mb-2 text-sm font-bold">Tentativas de impressão</h3>{attempts.map(a=><div key={a.id} className="grid gap-1 border-t py-3 text-sm sm:grid-cols-4"><strong>#{a.number} · {a.status===3?"Em execução":a.status===5?"Concluída":a.status===6?"Falha":"Registrada"}</strong><span>{duration(a.actualSeconds??a.estimatedSeconds)}</span><span>{num(a.grams)} g</span><span className="text-slate-500">{a.operator||"—"}</span>{a.notes&&<p className="text-xs text-slate-600 sm:col-span-4">{a.notes}</p>}</div>)}</section>}
  {[7,8,10].includes(o.status)&&d.capabilities.manageOrder&&<form className={box+" space-y-3"} onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);try{act("addMaterial",materialLine(d,str(f,"selection"),number(f,"quantity")));}catch{}}}><h3 className="text-sm font-bold">Reservar material adicional</h3><fieldset disabled={busy} className="grid gap-2 sm:grid-cols-[2fr_1fr_auto]"><Select label="Material" name="selection" options={materialOptions(d).filter(x=>o.status!==10||x.value.startsWith("supply:"))}/><Field label="Quantidade (g ou un.)" name="quantity" type="number" min={0.001} step="0.001"/><button className={secondary+" self-end"}>Reservar</button></fieldset></form>}
  {o.status===7&&d.capabilities.execute&&<form ref={actionRef} className={box+" space-y-3 scroll-mt-24"} onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);act("start",{printerId:str(f,"printerId"),seconds:number(f,"seconds")});}}><h3 className="font-bold">Iniciar tentativa</h3><fieldset disabled={busy} className="grid gap-3 sm:grid-cols-2"><Select label="Impressora disponível" name="printerId" value={o.printerId} options={d.printers.filter(x=>x.status===1).map(x=>({value:x.id,label:x.name+" · "+x.code}))}/><Field label="Tempo estimado desta tentativa (segundos)" name="seconds" type="number" min={1} value={o.seconds}/></fieldset><button className={primary} disabled={busy||filaments.length===0}>Iniciar impressão</button>{filaments.length===0&&<p className="text-xs text-amber-700">Reserve filamento antes de iniciar.</p>}</form>}
  {o.status===8&&d.capabilities.execute&&<form ref={actionRef} className={box+" space-y-3 scroll-mt-24"} onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);act("finish",{attemptId:o.activeAttemptId,success,seconds:number(f,"seconds"),laborSeconds:number(f,"laborSeconds"),producedQuantity:success?number(f,"producedQuantity"):0,notes:str(f,"notes"),actuals:filaments.map(a=>({allocationId:a.id,quantity:number(f,"actual_"+a.id)}))});}}><h3 className="font-bold">Registrar resultado da impressão</h3><fieldset disabled={busy} className="space-y-3"><label className="flex items-center gap-2 text-sm"><input type="radio" checked={success} onChange={()=>setSuccess(true)}/> Impressão concluída</label><label className="flex items-center gap-2 text-sm"><input type="radio" checked={!success} onChange={()=>setSuccess(false)}/> Falha / refugo</label>{actualFields(filaments)}<div className="grid gap-3 sm:grid-cols-3"><Field label="Tempo real de máquina (segundos)" name="seconds" type="number" min={success?1:0}/><Field label="Tempo humano (segundos)" name="laborSeconds" type="number" min={0} value={0}/>{success&&<Field label="Peças produzidas nesta tentativa" name="producedQuantity" type="number" min={1} max={o.quantity-o.produced+o.rejected} value={o.quantity-o.produced+o.rejected}/>}</div><Field label="Observação / motivo da falha" name="notes" required={!success}/></fieldset><button disabled={busy} className={primary}>Confirmar consumo e resultado</button></form>}
  {o.status===10&&d.capabilities.quality&&<form ref={actionRef} className={box+" space-y-3 scroll-mt-24"} onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);act("quality",{approvedQuantity:number(f,"approvedQuantity"),rejectedQuantity:number(f,"rejectedQuantity"),laborSeconds:number(f,"laborSeconds"),notes:str(f,"notes"),actuals:supplies.map(a=>({allocationId:a.id,quantity:number(f,"actual_"+a.id)}))});}}><h3 className="font-bold">Montagem e inspeção de qualidade</h3><fieldset disabled={busy} className="space-y-3">{actualFields(supplies)}<div className="grid gap-3 sm:grid-cols-3"><Field label="Peças aprovadas" name="approvedQuantity" type="number" min={0} max={pending} value={target===7?0:pending}/><Field label="Peças rejeitadas" name="rejectedQuantity" type="number" min={0} max={pending} value={target===7?pending:0}/><Field label="Tempo humano de montagem (segundos)" name="laborSeconds" type="number" min={0} value={0}/></div><Field label="Observações de qualidade" name="notes" required={false}/></fieldset><button disabled={busy} className={primary}>Concluir inspeção</button></form>}
  {[7,10].includes(o.status)&&d.capabilities.manageOrder&&<form className="rounded-xl border border-red-200 bg-red-50 p-4 space-y-3" onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);if(window.confirm("Cancelar esta OS? Consumos confirmados permanecerão no histórico."))act("cancel",{reason:str(f,"reason")});}}><Field label="Motivo de cancelamento" name="reason"/><button disabled={busy} className="rounded-lg border border-red-300 bg-white px-3 py-2 text-sm font-semibold text-red-700">Cancelar OS e liberar reservas</button></form>}
  {o.status===12&&<div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-900"><CheckCircle2 className="mr-2 inline" size={18}/>{o.orderType===1?(o.stockPostedAt?String(o.stockQuantity)+" unidade(s) recebidas no estoque de acabados. "+(o.accountingState==="PENDING_CONFIGURATION"?"Apropriação contábil pendente de configuração.":""):"Entrada de estoque ainda não confirmada."):o.saleId?"Produção faturada. Consulte a venda vinculada.":d.billingReady?"Produção aprovada. Disponível para faturamento interno.":"Produção aprovada. Faturamento indisponível nesta configuração."}{o.orderType===1?<a href="/inventory" className="ml-2 underline font-semibold">Consultar estoque</a>:o.saleId?<a href="/sales" className="ml-2 underline font-semibold">Consultar PDV</a>:d.billingReady&&<a href={"/sales?factoryOrderId="+encodeURIComponent(o.id)} className="ml-2 underline font-semibold">Abrir no caixa</a>}</div>}
 </div>;
}
function LibraryPanel({d,send,refresh,busy}:{d:FactoryData;send:Send;refresh:()=>Promise<boolean>;busy:boolean}){
 const [mode,setMode]=useState<"asset"|"version"|"recipe"|null>(null),[selected,setSelected]=useState(""),[localBusy,setLocalBusy]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState(""),[lines,setLines]=useState<{key:number;balanceId:string;qty:string}[]>([{key:1,balanceId:"",qty:""}]);const seq=useRef(2),pending=useRef<{key:string;id:string}|null>(null);
 const reset=()=>{setMode(null);setError("");setNotice("");};
 const upload=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(localBusy)return;const form=new FormData(e.currentTarget),f=form.get("file");if(!(f instanceof File)||f.size<1||f.size>2097152){setError("Selecione um arquivo de até 2 MiB.");return;}setLocalBusy(true);setError("");setNotice("");try{const digest=Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",await f.arrayBuffer()))).map(x=>x.toString(16).padStart(2,"0")).join("");const key=JSON.stringify([selected,form.get("revision"),form.get("notes"),f.name,digest]);const id=pending.current?.key===key?pending.current.id:crypto.randomUUID();pending.current={key,id};form.set("assetId",selected);form.set("requestId",id);const r=await fetch("/api/manufacturing/files",{method:"POST",body:form});const j=await r.json();if(!r.ok)throw Error(j.error||"Falha no envio.");pending.current=null;setNotice("Versão registrada. Revise os metadados antes de usar.");setMode(null);await refresh();}catch(e){setError(e instanceof Error?e.message:"Falha ao enviar.");}finally{setLocalBusy(false);}};
 const chooseRecipe=(id:string)=>{setSelected(id);setLines([{key:seq.current++,balanceId:"",qty:""}]);setMode("recipe");setError("");setNotice("");};
 const selectedVersion=d.versions.find(v=>v.id===selected);
 return <div className="space-y-4">
 <div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-bold">Biblioteca de projetos e fichas técnicas</h2><p className="text-xs text-slate-500">Arquivos versionados, licença, metadados de fatiamento e lista de materiais por lote.</p></div>{d.capabilities.libraryManage&&<button className={primary} disabled={busy||localBusy} onClick={()=>{setMode("asset");setError("");setNotice("");}}>+ Projeto</button>}</div>
 {error&&<p role="alert" className="rounded-lg bg-red-50 p-3 text-sm text-red-700">{error}</p>}{notice&&<p role="status" className="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-800">{notice}</p>}
 {mode==="asset"&&<form className={box+" space-y-3"} onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);void send("createAsset",{code:str(f,"code"),title:str(f,"title"),category:str(f,"category"),description:str(f,"description"),license:str(f,"license"),author:str(f,"author"),commercialAllowed:f.commercial==="on"}).then(reset).catch(()=>{});}}><h3 className="font-bold">Novo projeto</h3><fieldset disabled={busy} className="grid gap-3 sm:grid-cols-2"><Field name="code" label="Código"/><Field name="title" label="Título"/><Field name="category" label="Categoria"/><Field name="license" label="Licença de uso"/><Field name="author" label="Autor" required={false}/><Field name="description" label="Descrição" required={false}/><label className="flex gap-2 text-sm sm:col-span-2"><input type="checkbox" name="commercial"/>Confirmo que a licença permite uso comercial.</label></fieldset><div className="flex gap-2"><button className={primary} disabled={busy}>Salvar projeto</button><button type="button" className={secondary} onClick={reset}>Cancelar</button></div></form>}
 {mode==="version"&&<form className={box+" space-y-3"} onSubmit={upload}><h3 className="font-bold">Nova revisão · {d.library.find(a=>a.id===selected)?.title}</h3><fieldset disabled={localBusy||busy} className="grid gap-3 sm:grid-cols-2"><Field name="revision" label="Revisão (ex.: V1)"/><Field name="notes" label="Notas técnicas" required={false}/><label className="block text-xs font-medium text-slate-600 sm:col-span-2">Arquivo G-code, 3MF ou STL<input type="file" name="file" accept=".gcode,.3mf,.stl" required className={input}/></label></fieldset><p className="text-xs text-slate-500">Até 2 MiB por arquivo no armazenamento inicial. Arquivos são privados e não são executados. Projetos sem metadados exigem preenchimento manual.</p><div className="flex gap-2"><button className={primary} disabled={localBusy||busy}>{localBusy?"Validando arquivo…":"Registrar versão"}</button><button type="button" className={secondary} disabled={localBusy} onClick={reset}>Cancelar</button></div></form>}
 {mode==="recipe"&&<form className={box+" space-y-3"} onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);void send("createRecipe",{versionId:selected,batchQuantity:number(f,"batchQuantity"),seconds:number(f,"seconds"),laborSeconds:number(f,"laborSeconds"),notes:str(f,"notes"),lines:lines.map(x=>({balanceId:x.balanceId,quantity:Number(x.qty)}))}).then(reset).catch(()=>{});}}><h3 className="font-bold">Ficha técnica · {selectedVersion?.revision}</h3><fieldset disabled={busy} className="space-y-3"><div className="grid gap-3 sm:grid-cols-3"><Field label="Peças por lote" name="batchQuantity" type="number" min={1} value={1}/><Field label="Tempo de máquina por lote (s)" name="seconds" type="number" min={1} value={selectedVersion?.metadata?.plates.length===1?selectedVersion.metadata.plates[0].seconds??undefined:undefined}/><Field label="Tempo humano por lote (s)" name="laborSeconds" type="number" min={0} value={0}/></div><Field name="notes" label="Observações da ficha" required={false}/><p className="text-xs text-slate-600">Materiais totais de um lote, por SKU configurado; não selecione rolos físicos na ficha.</p>{lines.map(l=><div key={l.key} className="grid gap-2 sm:grid-cols-[2fr_1fr_auto]"><select className={input} required value={l.balanceId} onChange={e=>setLines(x=>x.map(y=>y.key===l.key?{...y,balanceId:e.target.value}:y))}><option value="">Selecione material</option>{d.balances.filter(b=>b.kind).map(b=><option key={b.id} value={b.id}>{b.material} {b.color} · {b.name} · {b.warehouse}</option>)}</select><input className={input} aria-label="Quantidade em gramas ou unidades" required type="number" min={0.001} step="0.001" value={l.qty} onChange={e=>setLines(x=>x.map(y=>y.key===l.key?{...y,qty:e.target.value}:y))}/><button type="button" className={secondary} onClick={()=>setLines(x=>x.filter(y=>y.key!==l.key))}>Remover</button></div>)}<button type="button" className={secondary} onClick={()=>setLines(x=>[...x,{key:seq.current++,balanceId:"",qty:""}])}>+ Material</button></fieldset><p className="text-xs text-slate-500">Ficha imutável por revisão. Para alterar a composição, crie nova revisão do projeto.</p><div className="flex gap-2"><button className={primary} disabled={busy}>Salvar ficha</button><button type="button" className={secondary} onClick={reset}>Cancelar</button></div></form>}
 {d.library.map(a=><section key={a.id} className={box+" space-y-3"}><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-bold"><FolderCode size={18} className="mr-2 inline text-purple-700"/>{a.title}</h3><p className="text-xs text-slate-500">{a.code} · {a.category} · {a.license} · {a.versions} versões</p><p className="text-xs text-slate-600">{a.commercialAllowed?"Uso comercial autorizado":"Uso comercial não autorizado"}{a.author?" · "+a.author:""}</p></div>{d.capabilities.libraryManage&&<button className={secondary} disabled={busy||localBusy} onClick={()=>{setSelected(a.id);setMode("version");setError("");}}>+ Revisão</button>}</div>{a.description&&<p className="text-sm text-slate-600">{a.description}</p>}
 {d.versions.filter(v=>v.assetId===a.id).map(v=>{const r=d.recipes.find(r=>r.versionId===v.id);return <div key={v.id} className="rounded-xl border bg-slate-50 p-3 space-y-2"><div className="flex flex-wrap justify-between gap-2"><div><p className="text-sm font-bold">{v.revision} · {v.format}</p><p className="text-xs text-slate-500">{v.filename||"Arquivo legado"} · {num(v.bytes/1024)} KiB</p></div><div className="flex flex-wrap gap-2">{v.downloadable&&<a className={secondary} href={"/api/manufacturing/files?versionId="+encodeURIComponent(v.id)}>Baixar arquivo</a>}{d.capabilities.libraryManage&&v.downloadable&&!r&&<button className={secondary} disabled={busy||localBusy} onClick={()=>chooseRecipe(v.id)}>Criar ficha</button>}</div></div>
 {v.metadata?.warnings.map((w,i)=><p key={i} className="text-xs text-amber-700">{w}</p>)}{v.metadata?.plates.map(p=><div key={p.index} className="rounded-lg border bg-white p-2 text-xs"><strong>Bandeja {p.index}</strong><p>{duration(p.seconds)} · {num(p.totalGrams)} g {p.preparationSeconds!==null?" · preparo "+duration(p.preparationSeconds):""}</p>{p.filaments.map(f=><p key={f.slot}>Slot {f.slot} · {f.material||"Material não informado"} · {f.color||"Cor não informada"} · {num(f.grams)} g</p>)}{p.warnings.map((w,i)=><p key={i} className="text-amber-700">{w}</p>)}</div>)}
 {r&&<div className="rounded-lg border border-emerald-200 bg-white p-2 text-xs"><strong>Ficha técnica · {r.batchQuantity} peças · {duration(r.seconds)}</strong>{r.lines.map(l=><p key={l.balanceId}>{l.material} {l.color} · {num(l.quantity)} {l.kind==="FILAMENT"?"g":"un."}</p>)}</div>}
 </div>})}</section>)}{d.library.length===0&&<Empty>Nenhum projeto cadastrado.</Empty>}
 </div>;
}

export default function FactoryWorkspace({estimator}:{estimator:React.ReactNode}){
 const [dragId,setDragId]=useState<string|null>(null),[dropStage,setDropStage]=useState<number|null>(null);const [d,setData]=useState<FactoryData|null>(null),[tab,setTab]=useState("kanban"),[modal,setModal]=useState<Modal|null>(null),[busy,setBusy]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(""),[notice,setNotice]=useState(""),[search,setSearch]=useState("");const requestKeys=useRef(new Map<string,string>());const running=useRef(false);
 const load=useCallback(async()=>{setLoading(true);setError("");try{const res=await fetch("/api/manufacturing/factory",{cache:"no-store"});const data=await res.json();if(!res.ok){const cid=res.headers.get("X-Correlation-Id");throw new Error((data.error||"Não foi possível carregar a fábrica.")+(cid?" Referência: "+cid:""));}setData(data);return true;}catch(e){setData(null);setError(e instanceof Error?e.message:"Falha ao carregar.");return false;}finally{setLoading(false);}},[]);
 useEffect(()=>{void load();},[load]);
 const send:Send=async(action,data,refresh=true)=>{if(running.current)throw new Error("Operação em andamento.");running.current=true;setBusy(true);setError("");setNotice("");const key=JSON.stringify([action,data]);const req=requestKeys.current.get(key)||crypto.randomUUID();requestKeys.current.set(key,req);try{const res=await fetch("/api/manufacturing/factory",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action,requestId:req,data}),cache:"no-store"});const payload=await res.json();if(!res.ok)throw new Error(payload.error||"Não foi possível concluir.");requestKeys.current.delete(key);if(refresh){setNotice("Operação registrada.");await load();}return payload.result;}catch(e){setError(e instanceof Error?e.message:"Falha na operação.");throw e;}finally{running.current=false;setBusy(false);}};
 const close=()=>{if(!busy)setModal(null);};const finishClose=()=>setModal(null);
 const tabs=[{id:"dashboard",label:"Visão geral"},{id:"kanban",label:"Kanban"},{id:"orders",label:"Ordens de serviço"},{id:"printers",label:"Impressoras"},{id:"filaments",label:"Filamentos"},{id:"supplies",label:"Insumos"},{id:"purchases",label:"Compras"},{id:"quote",label:"Calculadora"},{id:"library",label:"Biblioteca"},{id:"reports",label:"Relatórios"}];
 const matches=(s:string)=>s.toLocaleLowerCase("pt-BR").includes(search.toLocaleLowerCase("pt-BR"));const filtered=d?.orders.filter(o=>matches(o.number+" "+o.title+" "+o.customer))||[];const selected=d?.orders.find(o=>o.id===modal?.id);const selectedPrinter=d?.printers.find(p=>p.id===modal?.id);
 const detail=(o:Order,target?:number)=>{if(busy||loading||!d)return;if(target!==undefined&&!canMoveFactoryOrder(o.status,target,d.capabilities)){setError("Esta transição não é permitida para a situação atual ou suas permissões.");return;}setError("");setModal({kind:"detail",id:o.id,target});};
 return <main className="flex min-w-0 flex-1 flex-col overflow-hidden bg-slate-50">
  <header className="border-b bg-white px-5 py-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-[11px] font-bold uppercase tracking-wider text-purple-700">MOD-10 · Fábrica digital</p><h1 className="flex items-center gap-2 text-2xl font-bold text-slate-900"><Printer size={25} className="text-purple-700"/>Fábrica 3D</h1><p className="mt-1 text-xs text-slate-500">Produção, materiais, custos e rastreabilidade</p></div><div className="flex gap-2"><button className={secondary} disabled={loading||busy} onClick={()=>{setError("");void load();}}>Atualizar</button>{d?.capabilities.order&&<button className={primary} disabled={busy} onClick={()=>setModal({kind:"order"})}><Plus size={17}/> Nova OS</button>}</div></div></header>
  <nav aria-label="Submódulos da fábrica" className="flex shrink-0 gap-1 overflow-x-auto border-b bg-white px-4">{tabs.map(x=><button key={x.id} onClick={()=>{setTab(x.id);setSearch("");}} className={"whitespace-nowrap border-b-2 px-3 py-3 text-xs font-semibold "+(tab===x.id?"border-purple-600 text-purple-700":"border-transparent text-slate-500 hover:text-slate-900")}>{x.label}</button>)}</nav>
  <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4">
   {error&&<div role="alert" className="flex justify-between gap-2 rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-800"><span>{error}</span><button onClick={()=>setError("")} aria-label="Dispensar erro">×</button></div>}
   {notice&&<div role="status" className="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800">{notice}</div>}
   {loading?<Empty>Carregando dados da fábrica…</Empty>:!d?<Empty>Dados indisponíveis. Utilize Atualizar para tentar novamente.</Empty>:<>
    {(d.legacy.orders>0||d.legacy.spools>0)&&<div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900"><AlertTriangle className="mr-1 inline" size={15}/> Existem {d.legacy.orders} ordens e {d.legacy.spools} rolos legados preservados, aguardando reconciliação. Eles não são convertidos automaticamente.</div>}
    {["dashboard","kanban","reports"].includes(tab)&&<div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{stages.map(s=><div key={s.id} className={box+" border-t-4 "+s.tone}><p className="text-xs font-semibold text-slate-500">{s.name}</p><p className="mt-2 text-3xl font-bold text-slate-900">{s.id===7?d.summary.queued:s.id===8?d.summary.printing:s.id===10?d.summary.assembly:d.summary.ready}</p></div>)}</div>}
    {tab==="dashboard"&&<div className="grid gap-4 md:grid-cols-2"><section className={box}><h2 className="font-bold">Capacidade produtiva</h2><p className="mt-3 text-sm">{d.printers.filter(p=>p.status===1).length} impressoras disponíveis de {d.printers.length}</p><p className="mt-2 text-sm">{d.spools.filter(s=>s.active&&s.remainingGrams<=100).length} rolos com até 100 g</p><p className="mt-2 text-sm">{d.summary.cancelled} OS canceladas</p></section>{d.capabilities.costs&&<section className={box}><h2 className="font-bold">Custos registrados · todas as OS</h2><p className="mt-3 text-2xl font-bold">{money(d.summary.actualCost)}</p><p className="mt-2 text-sm text-slate-600">Refugo de material: {money(d.summary.wasteCost)}</p><p className="mt-2 text-xs text-slate-500">Não representa receita ou caixa recebido.</p></section>}</div>}
    {["kanban","orders"].includes(tab)&&<div className="relative max-w-md"><Search size={16} className="absolute left-3 top-3 text-slate-400"/><input className={input+" pl-9"} placeholder="Buscar OS, cliente ou produto" value={search} onChange={e=>setSearch(e.target.value)}/></div>}
    {tab==="kanban"&&<><p className="text-xs text-slate-600">Arraste um cartão para uma etapa permitida ou utilize a ação no cartão. Confirme os dados da operação para atualizar a ordem e o estoque.</p><div className="grid gap-3 xl:grid-cols-4 md:grid-cols-2">{stages.map(s=>{
     const dragging=d.orders.find(o=>o.id===dragId),allowed=!!dragging&&!busy&&canMoveFactoryOrder(dragging.status,s.id,d.capabilities),cards=filtered.filter(o=>o.status===s.id);
     return <section key={s.id} aria-label={s.name} className={"min-h-[320px] rounded-xl border border-t-4 p-3 transition-colors "+s.tone+" "+(allowed?(dropStage===s.id?"border-purple-500 bg-purple-100 ring-2 ring-purple-300":"border-purple-300 bg-purple-50"):"bg-slate-100")} onDragOver={e=>{if(allowed){e.preventDefault();e.dataTransfer.dropEffect="move";if(dropStage!==s.id)setDropStage(s.id);}}} onDragLeave={e=>{if(!e.currentTarget.contains(e.relatedTarget as Node|null))setDropStage(old=>old===s.id?null:old);}} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData("application/x-hbstudio-factory-order")||dragId;const o=d.orders.find(x=>x.id===id);setDragId(null);setDropStage(null);if(o&&o.status!==s.id)detail(o,s.id);}}>
     <h2 className="mb-3 flex justify-between text-sm font-bold text-slate-700">{s.name}<span className="rounded-full bg-white px-2 py-0.5 text-xs">{cards.length}</span></h2>{allowed&&<p className="mb-2 rounded-lg border border-dashed border-purple-300 p-2 text-center text-xs font-semibold text-purple-700">Solte para registrar a transição</p>}
     <div className="space-y-2">{cards.map(o=>{const moves=factoryTransitions(o.status,d.capabilities);return <article key={o.id} draggable={!busy&&moves.length>0} onDragStart={e=>{if(busy||!moves.length){e.preventDefault();return;}e.dataTransfer.effectAllowed="move";e.dataTransfer.setData("application/x-hbstudio-factory-order",o.id);e.dataTransfer.setData("text/plain",o.id);setDragId(o.id);}} onDragEnd={()=>{setDragId(null);setDropStage(null);}} className={"space-y-2 rounded-xl border bg-white p-3 shadow-sm hover:border-purple-300 "+(moves.length&&!busy?"cursor-grab active:cursor-grabbing":"")+(dragId===o.id?" opacity-60":"")}><button type="button" disabled={busy} onClick={()=>detail(o)} className="block w-full space-y-2 text-left"><p className="text-[11px] font-mono text-slate-500">{o.number}</p><p className="text-sm font-bold text-slate-900">{o.title}</p><p className="text-xs text-slate-600">{o.customer}</p><div className="flex flex-wrap gap-2 text-xs text-slate-500"><span>{o.quantity} peças</span><span>· {duration(o.seconds)}</span></div>{o.dueAt&&<p className="text-xs">Prazo: {date(o.dueAt)}</p>}{o.approvedPrice!==null&&<p className="text-sm font-semibold">{money(o.approvedPrice)}</p>}{o.failureReason&&<p className="text-xs text-amber-700">Ocorrência registrada</p>}</button>
     {moves.length>0&&<div className="space-y-2 border-t border-slate-100 pt-2"><button type="button" disabled={busy} onClick={()=>detail(o,moves[0].target)} className={primary+" w-full !px-2 !py-1.5 !text-xs"}>{moves[0].label} →</button>{moves.length>1&&<button type="button" disabled={busy} onClick={()=>detail(o,moves[1].target)} className="w-full rounded-md border border-slate-200 px-2 py-1.5 text-xs text-slate-600 hover:bg-slate-50 disabled:opacity-50">{moves[1].label}</button>}</div>}</article>})}{cards.length===0&&<Empty>Nenhuma OS nesta etapa.</Empty>}</div></section>})}</div></>}
    {tab==="orders"&&<section className={box+" overflow-x-auto"}><table className="w-full text-left text-sm"><thead className="text-xs text-slate-500"><tr>{["OS","Cliente / produto","Situação","Quantidade","Prazo","Preço","Ação"].map(x=><th className="p-2" key={x}>{x}</th>)}</tr></thead><tbody>{filtered.map(o=><tr className="border-t" key={o.id}><td className="p-2 font-mono text-xs">{o.number}</td><td className="p-2"><strong>{o.title}</strong><p className="text-xs text-slate-500">{o.customer}</p></td><td className="p-2">{orderStatus[o.status]||o.status}</td><td className="p-2">{o.quantity}</td><td className="p-2 text-xs">{date(o.dueAt)}</td><td className="p-2">{money(o.approvedPrice)}</td><td className="p-2"><button className={secondary} onClick={()=>detail(o)}>Abrir</button>{factoryTransitions(o.status,d.capabilities).slice(0,1).map(m=><button key={m.target} disabled={busy} className={primary+" ml-1 !text-xs"} onClick={()=>detail(o,m.target)}>{m.label}</button>)}</td></tr>)}</tbody></table>{filtered.length===0&&<Empty>Nenhuma ordem encontrada.</Empty>}</section>}
    {tab==="printers"&&<><div className="flex justify-between"><h2 className="text-lg font-bold">Parque de impressoras</h2>{d.capabilities.printer&&<button className={primary} onClick={()=>setModal({kind:"printer"})}>+ Impressora</button>}</div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{d.printers.map(p=><section className={box+" space-y-3"} key={p.id}><div className="flex justify-between gap-2"><div><p className="text-xs font-mono text-slate-500">{p.code}</p><h3 className="font-bold">{p.name}</h3><p className="text-xs text-slate-500">{p.manufacturer} {p.model}</p></div><span className="text-xs font-semibold text-purple-700">{printerStatus[p.status]||p.status}</span></div><div className="grid grid-cols-2 gap-2 rounded-lg bg-slate-50 p-3 text-xs"><span>Potência média: {num(p.averageWatts)} W</span><span>Hora-máquina: {money(p.machineHour)}</span><span>Área: {p.buildVolume}</span><span>Slots: {p.slotCount}</span></div><div className="grid grid-cols-2 gap-2">{Array.from({length:p.slotCount},(_,i)=>{const slot=d.slots.find(s=>s.printerId===p.id&&s.slot===i+1);const spool=d.spools.find(s=>s.id===slot?.spoolId);return <div key={i} className="rounded-lg border p-2 text-xs"><strong>Slot {i+1}</strong><p>{spool?spool.material+" "+spool.color+" "+spool.code:"Livre"}</p>{spool&&<p>{num(spool.remainingGrams)} g</p>}</div>})}</div>{p.notes&&<p className="text-xs text-slate-600">{p.notes}</p>}<div className="flex flex-wrap gap-2">{d.capabilities.printerStatus&&[1,7,8].includes(p.status)&&<button className={secondary} onClick={()=>setModal({kind:"printerStatus",id:p.id})}>Situação</button>}{d.capabilities.slot&&p.status===1&&<button className={secondary} onClick={()=>setModal({kind:"slot",id:p.id})}>Gerenciar slots</button>}</div></section>)}</div>{d.printers.length===0&&<Empty>Nenhuma impressora cadastrada.</Empty>}</>}
    {["filaments","supplies"].includes(tab)&&<><div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="text-lg font-bold">{tab==="filaments"?"Estoque de filamentos":"Estoque de insumos"}</h2><p className="text-xs text-slate-500">Integrado ao saldo central do ERP</p></div><div className="flex flex-wrap gap-2">{d.capabilities.inventory&&<a className={secondary} href="/inventory">Estoque central</a>}{d.capabilities.inventoryManage&&<><button className={secondary} onClick={()=>setModal({kind:tab==="filaments"?"configureFilament":"configureSupply"})}>Vincular SKU</button>{(d.capabilities.catalogIntake||tab==="filaments")&&<button className={primary} onClick={()=>setModal({kind:tab==="filaments"?"spools":"newSupply"})}>{tab==="filaments"?"+ Cadastrar filamento / rolos":"+ Cadastrar insumo"}</button>}</>}</div></div>
    {tab==="filaments"?<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{d.spools.map(s=><section key={s.id} className={box+" space-y-2"}><div className="flex justify-between gap-2"><div><p className="text-xs text-slate-500">{s.material} · {s.color}</p><h3 className="text-lg font-bold">Rolo {s.code}</h3></div><Weight className="text-purple-700" size={21}/></div><p className="text-2xl font-bold">{num(s.remainingGrams)} <span className="text-sm font-normal">g</span></p><div className="h-2 overflow-hidden rounded-full bg-slate-200"><div className="h-full rounded-full bg-purple-600" style={{width:Math.max(0,Math.min(100,s.remainingGrams/s.initialGrams*100))+"%"}}/></div><div className="grid grid-cols-2 text-xs text-slate-600"><span>Reservado: {num(s.reservedGrams)} g</span><span>Disponível: {num(s.availableGrams)} g</span><span>Lote: {s.batch||"—"}</span>{s.costPerGram!==null&&<span>Custo/kg: {money(s.costPerGram*1000)}</span>}</div></section>)}</div>:<section className={box+" overflow-x-auto"}><table className="w-full text-left text-sm"><thead className="text-xs text-slate-500"><tr>{["Insumo","SKU / depósito","Físico","Reservado","Disponível","Custo unitário"].map(x=><th key={x} className="p-2">{x}</th>)}</tr></thead><tbody>{d.balances.filter(x=>x.kind==="SUPPLY").map(x=><tr key={x.id} className="border-t"><td className="p-2 font-bold">{x.material}</td><td className="p-2 text-xs">{x.skuCode}<p>{x.warehouse}</p></td><td className="p-2">{num(x.onHand)}</td><td className="p-2">{num(x.reserved)}</td><td className="p-2">{num(x.available)}</td><td className="p-2">{money(x.averageCost)}</td></tr>)}</tbody></table></section>}{(tab==="filaments"?d.spools.length===0:!d.balances.some(x=>x.kind==="SUPPLY"))&&<Empty>Nenhum material registrado. Utilize o estoque central e vincule o SKU antes de registrar os insumos.</Empty>}</>}
    {tab==="purchases"&&<FactoryCommercePanel mode="purchases" refresh={load}/>}
    {tab==="reports"&&<FactoryCommercePanel mode="reports" refresh={load}/>}
    {tab==="quote"&&(d.capabilities.quote?estimator:<Empty>Permissão de orçamento e custos necessária.</Empty>)}
    {tab==="library"&&<LibraryPanel d={d} send={send} refresh={load} busy={busy}/>}
    {tab==="reports"&&<section className={box+" overflow-x-auto"}><h2 className="mb-3 text-lg font-bold">Custos por OS</h2><p className="mb-3 text-xs text-slate-500">Registros operacionais recentes. Valor aprovado não equivale a faturamento realizado.</p>{!d.capabilities.costs?<Empty>Permissão de custos necessária.</Empty>:<table className="w-full text-left text-sm"><thead className="text-xs text-slate-500"><tr>{["Ordem","Estimado","Realizado","Refugo","Preço aprovado"].map(x=><th key={x} className="p-2">{x}</th>)}</tr></thead><tbody>{d.orders.map(o=><tr className="border-t" key={o.id}><td className="p-2">{o.number} · {o.title}</td><td className="p-2">{money(o.estimatedCost)}</td><td className="p-2">{money(o.actualCost)}</td><td className="p-2">{money(o.wasteCost)}</td><td className="p-2">{money(o.approvedPrice)}</td></tr>)}</tbody></table>}</section>}
   </>}
  </div>
  {d&&modal&&<ModalFrame busy={busy} close={close} title={modal.kind==="detail"?((selected?.number||"Ordem de serviço")+(modal.target!==undefined&&selected?" — "+(factoryTransitions(selected.status,d.capabilities).find(x=>x.target===modal.target)?.label||"Acompanhar etapa"):"")):modal.kind==="order"?"Nova ordem de serviço":modal.kind==="printer"?"Nova impressora":modal.kind==="spools"?"Cadastrar filamento e rolos":modal.kind==="newSupply"?"Cadastrar insumo e estoque":modal.kind==="slot"?"Slots da impressora":modal.kind==="printerStatus"?"Situação do equipamento":"Vincular material ao estoque"}>
   {error&&<p role="alert" className="mb-3 rounded-lg bg-red-50 p-3 text-sm text-red-700">{error}</p>}
   {modal.kind==="order"&&<OrderForm d={d} send={send} busy={busy} close={finishClose}/>}
   {modal.kind==="printer"&&<PrinterForm send={send} busy={busy} close={finishClose}/>}
   {modal.kind==="configureFilament"&&<ConfigureForm d={d} kind="FILAMENT" send={send} busy={busy} close={finishClose}/>}
   {modal.kind==="configureSupply"&&<ConfigureForm d={d} kind="SUPPLY" send={send} busy={busy} close={finishClose}/>}
   {modal.kind==="spools"&&<SpoolForm d={d} send={send} busy={busy} close={finishClose} refresh={load}/>}
   {modal.kind==="newSupply"&&<CatalogIntakeForm context="supply" onDone={async()=>{await load();finishClose();}}/>}
   {modal.kind==="detail"&&selected&&<Detail key={selected.id+":"+selected.version+":"+modal.target} o={selected} d={d} send={send} busy={busy} target={modal.target} onTransition={finishClose}/>}
   {modal.kind==="printerStatus"&&selectedPrinter&&<form className="space-y-3" onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);void send("printerStatus",{printerId:selectedPrinter.id,status:number(f,"status"),notes:str(f,"notes")}).then(finishClose).catch(()=>{});}}><fieldset disabled={busy} className="space-y-3"><Select label="Situação" name="status" value={String(selectedPrinter.status)} options={[{value:"1",label:"Disponível"},{value:"7",label:"Manutenção"},{value:"8",label:"Fora de serviço"}]}/><Field label="Observações" name="notes" required={false}/></fieldset><button disabled={busy} className={primary}>Salvar</button></form>}
   {modal.kind==="slot"&&selectedPrinter&&<form className="space-y-3" onSubmit={e=>{e.preventDefault();const f=formValues(e.currentTarget);void send("assignSlot",{printerId:selectedPrinter.id,slot:number(f,"slot"),spoolId:str(f,"spoolId")||null}).then(finishClose).catch(()=>{});}}><fieldset disabled={busy} className="space-y-3"><Select label="Slot" name="slot" options={Array.from({length:selectedPrinter.slotCount},(_,i)=>({value:String(i+1),label:"Slot "+(i+1)}))}/><Select label="Rolo (deixe vazio para retirar)" name="spoolId" required={false} options={d.spools.filter(s=>s.active).map(s=>({value:s.id,label:s.material+" "+s.color+" "+s.code}))}/></fieldset><button disabled={busy} className={primary}>Salvar slot</button></form>}
  </ModalFrame>}
 </main>;
}
